import shapely.geometry as geom
from qiskit_metal.qlibrary.tlines.meandered import RouteMeander

class FCRouteMeander(RouteMeander):
    
    # Add your specific flip-chip options
    default_options = dict(
        RouteMeander.default_options,
        chip='C_chip',
        carve_out_chip='Q_chip',
        carve_out_extend_size='10um', # Additive margin on each side
    )

    def make(self):
        # 1. Call the parent class make() to generate the standard CPW on the bottom chip
        super().make()
        
        # 2. Grab the exact coordinate points generated by the parent (safer than qgeometry_table)
        pts = self.get_points()
        meander_line = geom.LineString(pts)
        
        # 3. Calculate the total footprint of the bottom CPW (trace + 2*gap)
        # Note: self.p already contains the parsed float values, so we can use them directly
        trace_w = self.p.trace_width
        gap_w = self.p.trace_gap
        total_cpw_width = trace_w + (2 * gap_w)
        
        # 4. Add the extra carve-out size (extend_size added to both sides)
        extend_size = self.p.carve_out_extend_size
        carveout_width = total_cpw_width + (2 * extend_size)
        
        # 5. Add the carveout to the opposite chip directly in the same make() loop
        self.add_qgeometry('path', 
                           {'top_carveout': meander_line},
                           width=carveout_width,
                           fillet=self.p.fillet,         # <--- Ensures the carveout curves match the CPW
                           chip=self.p.carve_out_chip,
                           subtract=True)